class n{constructor(i,t,s,m){this.minX=i,this.maxX=t,this.minY=s,this.maxY=m}contains(i){return this.containsXY(i[1],i[2])}containsTileRange(i){return this.minX<=i.minX&&i.maxX<=this.maxX&&this.minY<=i.minY&&i.maxY<=this.maxY}containsXY(i,t){return this.minX<=i&&i<=this.maxX&&this.minY<=t&&t<=this.maxY}equals(i){return this.minX==i.minX&&this.minY==i.minY&&this.maxX==i.maxX&&this.maxY==i.maxY}extend(i){i.minX<this.minX&&(this.minX=i.minX),i.maxX>this.maxX&&(this.maxX=i.maxX),i.minY<this.minY&&(this.minY=i.minY),i.maxY>this.maxY&&(this.maxY=i.maxY)}getHeight(){return this.maxY-this.minY+1}getSize(){return[this.getWidth(),this.getHeight()]}getWidth(){return this.maxX-this.minX+1}intersects(i){return this.minX<=i.maxX&&this.maxX>=i.minX&&this.minY<=i.maxY&&this.maxY>=i.minY}}export function createOrUpdate(h,i,t,s,m){return m!==void 0?(m.minX=h,m.maxX=i,m.minY=t,m.maxY=s,m):new n(h,i,t,s)}export default n;
